import{_ as o,o as e,c as t,a2 as l}from"./chunks/framework.CHeM0PsO.js";const q=JSON.parse('{"title":"第 6 课：认识 Codex 界面","description":"","frontmatter":{},"headers":[],"relativePath":"modules/module-2/lesson-6.md","filePath":"modules/module-2/lesson-6.md"}'),r={name:"modules/module-2/lesson-6.md"};function i(d,a,h,n,s,u){return e(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="第-6-课-认识-codex-界面" tabindex="-1">第 6 课：认识 Codex 界面 <a class="header-anchor" href="#第-6-课-认识-codex-界面" aria-label="Permalink to &quot;第 6 课：认识 Codex 界面&quot;">​</a></h1><blockquote><p>📌 <strong>学习目标</strong>：熟悉 Codex 桌面 App 的界面布局、核心功能和操作逻辑<br> ⏱️ <strong>预计时长</strong>：15 分钟<br> 🎯 <strong>本节节奏</strong>：界面导览 + 概念讲解</p></blockquote><hr><h2 id="一、界面概览" tabindex="-1">一、界面概览 <a class="header-anchor" href="#一、界面概览" aria-label="Permalink to &quot;一、界面概览&quot;">​</a></h2><p>打开 Codex 桌面 App 后，你会看到以下主要区域：</p><h3 id="左侧面板" tabindex="-1">左侧面板 <a class="header-anchor" href="#左侧面板" aria-label="Permalink to &quot;左侧面板&quot;">​</a></h3><ul><li><strong>对话管理</strong>：显示历史对话列表，可以快速切换或新建对话</li><li><strong>工作区（Workspace）</strong>：显示当前项目/文件夹的内容结构</li><li><strong>插件/技能</strong>：显示可用的内置技能和扩展功能</li></ul><h3 id="中间对话框" tabindex="-1">中间对话框 <a class="header-anchor" href="#中间对话框" aria-label="Permalink to &quot;中间对话框&quot;">​</a></h3><ul><li>这是你与 Codex 对话的主要区域</li><li>你可以在此输入文字指令、上传文件、查看 Codex 的回复和执行结果</li></ul><h3 id="右侧-底部面板-视版本而定" tabindex="-1">右侧/底部面板（视版本而定） <a class="header-anchor" href="#右侧-底部面板-视版本而定" aria-label="Permalink to &quot;右侧/底部面板（视版本而定）&quot;">​</a></h3><ul><li>文件预览区</li><li>代码编辑器</li><li>执行日志</li></ul><hr><h2 id="二、核心概念-工作区-workspace" tabindex="-1">二、核心概念：工作区（Workspace） <a class="header-anchor" href="#二、核心概念-工作区-workspace" aria-label="Permalink to &quot;二、核心概念：工作区（Workspace）&quot;">​</a></h2><p><strong>工作区是 Codex 最重要的概念之一。</strong></p><p>当你把一个文件夹设为工作区时，你实际上是在告诉 Codex：&quot;你可以在这个文件夹范围内读取、创建和修改文件。&quot;</p><h3 id="为什么需要工作区" tabindex="-1">为什么需要工作区？ <a class="header-anchor" href="#为什么需要工作区" aria-label="Permalink to &quot;为什么需要工作区？&quot;">​</a></h3><ol><li><strong>安全边界</strong>：Codex 只能在指定的工作区内操作，不会影响到其他文件</li><li><strong>上下文聚焦</strong>：Codex 可以读取工作区内的所有文件，理解你的项目结构</li><li><strong>结果可控</strong>：所有修改都在工作区内，方便追溯和管理</li></ol><h3 id="如何设置工作区" tabindex="-1">如何设置工作区？ <a class="header-anchor" href="#如何设置工作区" aria-label="Permalink to &quot;如何设置工作区？&quot;">​</a></h3><ol><li>在 Codex 界面中找到&quot;打开文件夹&quot;或&quot;选择工作区&quot;按钮</li><li>浏览到你的目标文件夹并确认</li><li>左侧面板会显示该文件夹的文件树结构</li></ol><hr><h2 id="三、权限模式" tabindex="-1">三、权限模式 <a class="header-anchor" href="#三、权限模式" aria-label="Permalink to &quot;三、权限模式&quot;">​</a></h2><p>Codex 提供三种权限模式，用于控制 AI 对文件的操作范围：</p><h3 id="_1-默认权限-推荐新手" tabindex="-1">1. 默认权限（推荐新手） <a class="header-anchor" href="#_1-默认权限-推荐新手" aria-label="Permalink to &quot;1. 默认权限（推荐新手）&quot;">​</a></h3><ul><li>Codex 在执行任何文件修改前都会先征求你的同意</li><li>最安全，适合刚开始使用的用户</li><li>你可以在每次操作前判断是否允许</li></ul><h3 id="_2-自动审查-推荐进阶用户" tabindex="-1">2. 自动审查（推荐进阶用户） <a class="header-anchor" href="#_2-自动审查-推荐进阶用户" aria-label="Permalink to &quot;2. 自动审查（推荐进阶用户）&quot;">​</a></h3><ul><li>Codex 可以自动执行操作，但你可以在事后查看和审计</li><li>效率更高，适合你已经信任 Codex 的工作方式</li><li>⚠️ 建议在操作重要文件前先备份</li></ul><h3 id="_3-完全访问-不推荐" tabindex="-1">3. 完全访问（不推荐） <a class="header-anchor" href="#_3-完全访问-不推荐" aria-label="Permalink to &quot;3. 完全访问（不推荐）&quot;">​</a></h3><ul><li>Codex 拥有对你工作区内文件的完全读写权限</li><li>风险最高，不建议新手使用</li><li>仅在你完全了解风险的情况下启用</li></ul><blockquote><p>⚠️ <strong>安全提醒</strong>：无论选择哪种权限模式，都不要在 Codex 中输入密码、银行卡号等敏感信息。</p></blockquote><hr><h2 id="四、本节实操任务" tabindex="-1">四、本节实操任务 <a class="header-anchor" href="#四、本节实操任务" aria-label="Permalink to &quot;四、本节实操任务&quot;">​</a></h2><ol><li>打开 Codex 桌面 App</li><li>创建一个测试文件夹（比如桌面上的&quot;Codex练习&quot;）</li><li>将该文件夹设为 Codex 的工作区</li><li>观察左侧面板的文件树变化</li><li>尝试将权限模式从&quot;默认权限&quot;切换到&quot;自动审查&quot;（体验一下即可，随时可改回来）</li></ol><hr><h2 id="五、本节小结" tabindex="-1">五、本节小结 <a class="header-anchor" href="#五、本节小结" aria-label="Permalink to &quot;五、本节小结&quot;">​</a></h2><table tabindex="0"><thead><tr><th>知识点</th><th>核心内容</th></tr></thead><tbody><tr><td>工作区</td><td>Codex 操作文件的范围，类似&quot;沙盒&quot;</td></tr><tr><td>左侧面板</td><td>对话管理 + 工作区文件树 + 技能列表</td></tr><tr><td>对话框</td><td>输入指令和查看结果的主要区域</td></tr><tr><td>权限模式</td><td>默认权限（安全）、自动审查（高效）、完全访问（高风险）</td></tr></tbody></table><hr><h2 id="六、下一步" tabindex="-1">六、下一步 <a class="header-anchor" href="#六、下一步" aria-label="Permalink to &quot;六、下一步&quot;">​</a></h2><p><a href="./lesson-7.html">→ 第 7 课：第一次对话</a></p>',38)])])}const x=o(r,[["render",i]]);export{q as __pageData,x as default};
